bounded_host_request.command:
set -euo pipefail
src=ec00440306f6d802310f48ff2dc4953beae61848
name=gace-createvdobot-videobot-poll-1
test "$(docker inspect -f '{{.State.Running}}' "$name")" = true || { echo VIDEO_EXISTING_POLLER_NOT_RUNNING; exit 61; }
test "$(git remote get-url origin | sed 's#\.git$##')" = "https://github.com/seigo-gace/create-videobot" || { echo VIDEO_REPO_ORIGIN_MISMATCH; exit 62; }
git fetch --no-tags origin refs/heads/feat/assistant-ai-and-sales-core >/dev/null 2>&1
test "$(git rev-parse FETCH_HEAD)" = "$src" || { echo VIDEO_SOURCE_CHANGED_ABORT; exit 63; }
target="$HOME/.local/share/gace-create-videobot/sticker-poll-$src"
if test ! -d "$target";then
  mkdir -p "$target"
  git archive "$src" | tar -x -C "$target"
fi
test -f "$target/src/telegram/creatorUi.mjs" || exit 64
grep -q "Myビデオを見る" "$target/src/telegram/creatorUi.mjs" || exit 65
grep -q 'replyToMessageId' "$target/src/telegram/creatorScreenTransport.mjs" || exit 66
docker build --network host --pull=false -f "$target/deploy/Dockerfile" -t create-videobot:poll-myvideo-$src "$target" >/dev/null 2>&1 || { echo VIDEO_BUILD_FAIL; exit 67; }
docker run --rm --network none --pull never --entrypoint /bin/sh create-videobot:poll-myvideo-$src -c 'grep -q "Myビデオを見る" /opt/videobot/src/telegram/creatorUi.mjs && command -v ffmpeg >/dev/null && test -f /opt/videobot/src/runtime/creatorPollingMain.mjs' >/dev/null || { echo VIDEO_IMAGE_VERIFY_FAIL; exit 68; }
token="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_telegram_token"}}{{.Source}}{{end}}{{end}}' "$name")"
dbpass="$(docker inspect -f '{{range .Mounts}}{{if eq .Destination "/run/secrets/videobot_db_password"}}{{.Source}}{{end}}{{end}}' "$name")"
test -f "$token" && test -f "$dbpass" || { echo VIDEO_SECRETS_NOT_MOUNTED; exit 69; }
pg="$(docker ps --format '{{.Names}}' | grep -Ei '(^|[-_])postgres([-_]|$)' || true)"
test "$(printf '%s\n' "$pg" | sed '/^$/d' | wc -l)" -eq 1 || { echo VIDEO_POSTGRES_AMBIGUOUS; exit 70; }
user="$(docker exec "$pg" sh -c 'printf %s "$POSTGRES_USER"')"
net="$(docker inspect -f '{{range $k,$v := .NetworkSettings.Networks}}{{println $k}}{{end}}' "$pg" | sed '/^$/d')"
test -n "$user" && test "$net" = deploy_default || { echo VIDEO_DATABASE_SETTINGS_MISMATCH; exit 71; }
other="$(docker ps --format '{{.Names}}' | grep -Ei 'create-videobot|createvdobot|videobot-poll|videobot-telegram' | grep -Fxv "$name" || true)"
test -z "$other" || { echo VIDEO_OTHER_POLLER_RUNNING; exit 72; }
export VIDEOBOT_TELEGRAM_TOKEN_SOURCE="$token" VIDEOBOT_DB_PASSWORD_SOURCE="$dbpass" GSERVER_POSTGRES_USER="$user" GSERVER_POSTGRES_NETWORK="$net"
docker image tag create-videobot:local-poll create-videobot:poll-rollback-myvideo
docker image tag create-videobot:poll-myvideo-$src create-videobot:local-poll
docker compose -p gace-createvdobot -f "$target/deploy/compose.videobot.poll.yaml" up -d --no-build --force-recreate videobot-poll >/dev/null 2>&1 || { echo VIDEO_DEPLOY_FAILED; exit 73; }
sleep 10
test "$(docker inspect -f '{{.State.Running}}' "$name")" = true || { echo VIDEO_POLLER_NOT_RUNNING; exit 74; }
docker logs --tail 100 "$name" 2>&1 | grep -q '^CREATOR_DM_POLL_READY=PASS$' || { echo VIDEO_POLLER_NOT_READY; exit 75; }
docker exec "$name" sh -c 'grep -q "Myビデオを見る" /opt/videobot/src/telegram/creatorUi.mjs && grep -q "replyToMessageId" /opt/videobot/src/telegram/creatorScreenTransport.mjs && command -v ffmpeg >/dev/null' || { echo VIDEO_LIVE_IMAGE_MISMATCH; exit 76; }
echo VIDEO_LIVE_MYVIDEOS_AND_PREVIEW_CODE=PASS
